import React, { useState, useEffect, useMemo } from 'react';
import { 
  Users, Calendar, ClipboardList, FileDown, 
  Upload, Play, Trash2, Printer, Plus, Settings, BarChart3, AlertCircle 
} from 'lucide-react';
import * as XLSX from 'xlsx';

const RosterApp = () => {
  // --- 1. STATE MANAGEMENT ---
  const [activeTab, setActiveTab] = useState('staff');
  const [staff, setStaff] = useState(() => JSON.parse(localStorage.getItem('roster_staff')) || []);
  const [holidays, setHolidays] = useState(() => JSON.parse(localStorage.getItem('roster_holidays')) || []);
  const [config, setConfig] = useState({ 
    start: '2026-04-01', 
    end: '2026-04-30',
    nightShiftsNeeded: 2,
    generalShiftsNeeded: 4 
  });
  const [roster, setRoster] = useState(null);

  useEffect(() => {
    localStorage.setItem('roster_staff', JSON.stringify(staff));
    localStorage.setItem('roster_holidays', JSON.stringify(holidays));
  }, [staff, holidays]);

  // --- 2. DATA UTILITIES (EXCEL & DATES) ---
  const formatExcelDate = (serial) => {
    if (!serial || isNaN(serial)) return serial;
    const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
    return date.toISOString().split('T')[0];
  };

  const exportTemplate = () => {
    const wb = XLSX.utils.book_new();
    const sWS = XLSX.utils.json_to_sheet(staff.map(s => ({ Name: s.name, Designation: s.designation, Role: s.role })));
    const hWS = XLSX.utils.json_to_sheet(holidays.map(h => ({ Date: h.date, Name: h.name })));
    XLSX.utils.book_append_sheet(wb, sWS, "Staff");
    XLSX.utils.book_append_sheet(wb, hWS, "Holiday");
    XLSX.writeFile(wb, "Roster_System_Data.xlsx");
  };

  const handleImport = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onload = (evt) => {
      const wb = XLSX.read(evt.target.result, { type: 'binary' });
      if (wb.SheetNames.includes('Staff')) {
        setStaff(XLSX.utils.sheet_to_json(wb.Sheets['Staff']).map(i => ({
          name: i.Name || i.name || '', designation: i.Designation || i.designation || '', role: i.Role || i.role || 'Junior'
        })));
      }
      if (wb.SheetNames.includes('Holiday')) {
        setHolidays(XLSX.utils.sheet_to_json(wb.Sheets['Holiday']).map(i => ({
          date: formatExcelDate(i.Date || i.date), name: i.Name || i.name || 'Holiday'
        })).filter(h => h.date));
      }
    };
    reader.readAsBinaryString(file);
  };

  // --- 3. THE GENERATION ENGINE ---
  const generateRoster = () => {
    const days = [];
    let cur = new Date(config.start);
    const stop = new Date(config.end);
    while (cur <= stop) {
      days.push(new Date(cur).toISOString().split('T')[0]);
      cur.setDate(cur.getDate() + 1);
    }

    // Logic: Assign "G" to everyone, but mark Sundays and Holidays as "OFF"
    const newRoster = staff.map(person => {
      const schedule = {};
      days.forEach(day => {
        const d = new Date(day);
        const isSunday = d.getDay() === 0;
        const isHoliday = holidays.some(h => h.date === day);
        
        if (isSunday || isHoliday) {
          schedule[day] = 'OFF';
        } else {
          schedule[day] = 'G'; // General Shift
        }
      });
      return { ...person, schedule };
    });

    setRoster({ days, data: newRoster });
    setActiveTab('roster');
  };

  // --- 4. UI COMPONENTS ---
  return (
    <div className="max-w-7xl mx-auto p-4 md:p-8 bg-slate-50 min-h-screen font-sans">
      <header className="flex flex-wrap justify-between items-center mb-8 gap-4 print:hidden">
        <div>
          <h1 className="text-3xl font-extrabold text-indigo-900 tracking-tight">Duty Roster Pro</h1>
          <p className="text-slate-500 font-medium">Internal Management System • Mumbai</p>
        </div>
        <div className="flex gap-3">
          <button onClick={exportTemplate} className="bg-white border-2 border-slate-200 p-2 px-4 rounded-lg text-sm font-bold flex items-center gap-2 hover:bg-slate-50 transition shadow-sm"><FileDown size={18}/> Export Template</button>
          <label className="bg-indigo-50 border-2 border-indigo-100 p-2 px-4 rounded-lg text-sm font-bold text-indigo-700 flex items-center gap-2 cursor-pointer hover:bg-indigo-100 transition shadow-sm">
            <Upload size={18}/> Import Excel
            <input type="file" className="hidden" onChange={handleImport} />
          </label>
        </div>
      </header>

      <nav className="flex space-x-1 bg-slate-200/50 p-1 rounded-xl mb-8 print:hidden">
        {['staff', 'holidays', 'config', 'roster'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`flex-1 py-3 text-sm font-bold rounded-lg transition capitalize flex items-center justify-center gap-2 ${activeTab === tab ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            {tab === 'staff' && <Users size={18}/>}
            {tab === 'holidays' && <Calendar size={18}/>}
            {tab === 'config' && <Settings size={18}/>}
            {tab === 'roster' && <ClipboardList size={18}/>}
            {tab}
          </button>
        ))}
      </nav>

      <main className="bg-white rounded-2xl shadow-xl border border-slate-200 p-6 md:p-8">
        {/* STAFF SECTION */}
        {activeTab === 'staff' && (
          <div className="overflow-x-auto">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-bold text-slate-800">Staff Members ({staff.length})</h2>
              <button onClick={() => setStaff([...staff, { name: '', designation: '', role: 'Junior' }])} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition"><Plus size={18}/> Add Row</button>
            </div>
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 text-slate-600 text-xs uppercase tracking-wider">
                  <th className="p-4 rounded-tl-lg">Name</th>
                  <th className="p-4">Designation</th>
                  <th className="p-4">Role</th>
                  <th className="p-4 text-right rounded-tr-lg">Remove</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {staff.map((s, i) => (
                  <tr key={i} className="hover:bg-slate-50/50 transition">
                    <td className="p-3"><input className="w-full p-2 border-0 bg-transparent focus:ring-2 focus:ring-indigo-500 rounded font-medium" value={s.name} onChange={e => { const n = [...staff]; n[i].name = e.target.value; setStaff(n); }} placeholder="Enter Name"/></td>
                    <td className="p-3"><input className="w-full p-2 border-0 bg-transparent focus:ring-2 focus:ring-indigo-500 rounded" value={s.designation} onChange={e => { const n = [...staff]; n[i].designation = e.target.value; setStaff(n); }} placeholder="e.g. Engineer"/></td>
                    <td className="p-3">
                      <select className="bg-slate-100 border-0 text-sm rounded-lg p-2 font-semibold" value={s.role} onChange={e => { const n = [...staff]; n[i].role = e.target.value; setStaff(n); }}>
                        <option value="Senior">Senior</option>
                        <option value="Junior">Junior</option>
                      </select>
                    </td>
                    <td className="p-3 text-right"><button onClick={() => setStaff(staff.filter((_, idx) => idx !== i))} className="text-slate-300 hover:text-red-500 p-2 transition"><Trash2 size={20}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* HOLIDAY SECTION */}
        {activeTab === 'holidays' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {holidays.map((h, i) => (
              <div key={i} className="p-5 border-2 border-indigo-50 rounded-2xl bg-gradient-to-br from-white to-indigo-50/30 flex justify-between items-center shadow-sm">
                <div>
                  <p className="font-bold text-indigo-900">{h.name}</p>
                  <p className="text-sm font-medium text-indigo-400">{h.date}</p>
                </div>
                <button onClick={() => setHolidays(holidays.filter((_, idx) => idx !== i))} className="text-indigo-200 hover:text-red-500 transition"><Trash2 size={20}/></button>
              </div>
            ))}
          </div>
        )}

        {/* CONFIG SECTION */}
        {activeTab === 'config' && (
          <div className="max-w-md mx-auto space-y-8 py-10">
            <div className="text-center mb-10"><h2 className="text-2xl font-bold text-slate-800">Generation Settings</h2><p className="text-slate-500">Define the period for your April roster</p></div>
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2"><label className="text-xs font-bold text-slate-500 uppercase">Start Date</label><input type="date" className="w-full p-3 bg-slate-100 border-0 rounded-xl font-bold" value={config.start} onChange={e => setConfig({...config, start: e.target.value})}/></div>
              <div className="space-y-2"><label className="text-xs font-bold text-slate-500 uppercase">End Date</label><input type="date" className="w-full p-3 bg-slate-100 border-0 rounded-xl font-bold" value={config.end} onChange={e => setConfig({...config, end: e.target.value})}/></div>
            </div>
            <button onClick={generateRoster} className="w-full bg-indigo-600 text-white p-5 rounded-2xl font-black text-lg shadow-xl shadow-indigo-200 hover:bg-indigo-700 hover:-translate-y-1 transition active:translate-y-0">Generate Duty Roster</button>
          </div>
        )}

        {/* ROSTER VIEW SECTION */}
        {activeTab === 'roster' && roster && (
          <div className="space-y-6">
            <div className="flex justify-between items-center print:hidden">
              <h2 className="text-xl font-bold text-slate-800">Final Roster: {config.start} to {config.end}</h2>
              <button onClick={() => window.print()} className="bg-slate-800 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-900 transition"><Printer size={18}/> Save as PDF</button>
            </div>
            <div className="overflow-x-auto border rounded-xl">
              <table className="w-full border-collapse text-[11px]">
                <thead>
                  <tr className="bg-slate-100">
                    <th className="border p-2 sticky left-0 bg-slate-100 z-10 min-w-[120px]">Staff Name</th>
                    {roster.days.map(d => (
                      <th key={d} className={`border p-2 min-w-[40px] ${new Date(d).getDay() === 0 ? 'bg-red-50 text-red-600' : ''}`}>
                        {d.split('-')[2]}<br/><span className="text-[8px] uppercase">{new Intl.DateTimeFormat('en-US', {weekday: 'short'}).format(new Date(d))}</span>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {roster.data.map((row, i) => (
                    <tr key={i} className="hover:bg-slate-50">
                      <td className="border p-2 font-bold sticky left-0 bg-white z-10 shadow-sm">{row.name}</td>
                      {roster.days.map(day => (
                        <td key={day} className={`border p-2 text-center font-bold ${row.schedule[day] === 'OFF' ? 'bg-slate-100 text-slate-400' : 'bg-emerald-50 text-emerald-700'}`}>
                          {row.schedule[day]}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default RosterApp;